-- Companion object-existence validation (non-tabular derived objects that COUNT(*) can't cover).
-- Run each SHOW then RESULT_SCAN; each should return >= 1 row. Parameterized on {{TARGET_DATABASE}}.{{TARGET_SCHEMA}}.
--   SHOW SEMANTIC VIEWS LIKE 'SV_PATIENT_EXPERIENCE_INTELLIGENCE' IN SCHEMA {{TARGET_DATABASE}}.{{TARGET_SCHEMA}};
--   SHOW AGENTS LIKE 'AGT_PATIENT_EXPERIENCE' IN SCHEMA {{TARGET_DATABASE}}.{{TARGET_SCHEMA}};
--   SHOW MODELS LIKE 'PX_DISSAT_RISK_XGB' IN SCHEMA {{TARGET_DATABASE}}.{{TARGET_SCHEMA}};
--   SHOW CORTEX SEARCH SERVICES LIKE 'COMMENT_SEARCH' IN SCHEMA {{TARGET_DATABASE}}.{{TARGET_SCHEMA}};
--   SHOW STREAMS LIKE 'CALL_RECORDING_STAGE_STREAM' IN SCHEMA {{TARGET_DATABASE}}.{{TARGET_SCHEMA}};
--   SHOW TASKS LIKE '%' IN SCHEMA {{TARGET_DATABASE}}.{{TARGET_SCHEMA}};   -- expect CALL_RECORDING_INGEST_TASK + MDL_DISSAT_RISK_SCORE_TASK
--   SHOW DYNAMIC TABLES LIKE 'CALL_TRANSCRIPT' IN SCHEMA {{TARGET_DATABASE}}.{{TARGET_SCHEMA}};  -- verify "refresh_mode" = INCREMENTAL
-- The derived-build skill runs these after checks.sql and treats a 0-row result as FAIL.
SELECT 'run the SHOW commands above; each must return >= 1 row (CALL_TRANSCRIPT + COMMENT_ENRICHED DTs must be INCREMENTAL)' AS NOTE;
